import{_ as t}from"./chunks/hinweise-it-dienstleister.aprHqZOH.js";import{_ as a,o as s,c as l,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/installation/serverinstallation-schule-svws-und-schild3.png",u="/bilder/installation/kennwoerter-db-schema-schild.jpg",D=JSON.parse('{"title":"Installation und Betrieb für IT-Dienstleister planen","description":"","frontmatter":{"title":"Installation und Betrieb für IT-Dienstleister planen","source_pageid":730,"source_revision":6911},"headers":[],"relativePath":"administration/installation/hinweise-fuer-it-dienstleister.md","filePath":"administration/installation/hinweise-fuer-it-dienstleister.md"}'),o={name:"administration/installation/hinweise-fuer-it-dienstleister.md"};function h(c,i,m,g,b,S){return s(),l("div",null,[...i[0]||(i[0]=[r('<h1 id="installation-und-betrieb-fur-it-dienstleister-planen" tabindex="-1">Installation und Betrieb für IT-Dienstleister planen <a class="header-anchor" href="#installation-und-betrieb-fur-it-dienstleister-planen" aria-label="Permalink to &quot;Installation und Betrieb für IT-Dienstleister planen&quot;">​</a></h1><p>Klären Sie vor der Installation Programmbausteine, Datenbankschemata, Ordnerstruktur und Benutzerrollen. Die Hinweise richten sich an die für Einrichtung und Betrieb verantwortlichen Personen.</p><p>Der folgenden Artikel beinhaltet Hinweise zur Installation der <strong>S</strong>chul<strong>V</strong>er<strong>W</strong>altungs<strong>S</strong>oftware, zu der auch SchILD-NRW 3 gehört. Die praktische Durchführung beschreibt <a href="/administration/installation/installation-svws-server-und-schild-nrw-3.html">SVWS-Server und SchILD-NRW 3 installieren</a>.</p><h2 id="programmbausteine" tabindex="-1">Programmbausteine <a class="header-anchor" href="#programmbausteine" aria-label="Permalink to &quot;Programmbausteine&quot;">​</a></h2><p><a href="/bilder/installation/hinweise-it-dienstleister.png"><img src="'+t+'" alt="Trennung von Frontend-Applikation, Logikserver und Datenbankserver" loading="lazy"></a></p><p><em>Trennung von Frontend-Applikation, Logikserver und Datenbankserver</em></p><p>Die neue SchILD-Version besteht nicht mehr aus zwei, sondern aus vier Programmbausteinen.</p><ul><li>Der SVWS-Server fungiert als Dienstprogramm, welches logische Aufgaben übernimmt und den Zugriff...</li><li>... auf die MariaDB-Datenbank regelt. Der Datenbankserver wird zusammen mit dem SVWS-Server installiert.</li><li>SchILD-NRW 3 dient als Anzeigeoberfläche der Datenbankdaten und übernimmt ebenfalls logische Aufgaben, die noch nicht im SVWS-Server implementiert wurden. SchILD-NRW 3 greift deshalb teilweise über den SVWS-Server und teilweise direkt auf die MariaDB zu.</li><li>Der SVWS-Client stellt die Technologie zur Anzeige der Datenbankdaten in einem Browserfenster zur Verfügung. Der SVWS-Client ist Bestandteil des SVWS-Servers und kann nur auf die logischen Aufgaben des SVWS-Servers zurückgreifen.</li></ul>',8),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Beachten Sie bitte unsere Videoanleitungen zur Installation des SVWS-Servers und von SchILD-NRW 3 in dieser Dokumentation.")],-1),r('<h2 id="datenbank-und-installation" tabindex="-1">Datenbank und Installation <a class="header-anchor" href="#datenbank-und-installation" aria-label="Permalink to &quot;Datenbank und Installation&quot;">​</a></h2><h3 id="datenbank-schemata" tabindex="-1">Datenbank-Schemata <a class="header-anchor" href="#datenbank-schemata" aria-label="Permalink to &quot;Datenbank-Schemata&quot;">​</a></h3><p>Ein <strong>Datenbankschema</strong> bezeichnet hier die Datenbank einer Schule innerhalb der MariaDB. Es enthält die von SVWS benötigten Tabellen und kann leer, bereits befüllt oder aus SchILD-NRW 2 migriert sein. „Schema“ bedeutet daher nicht, dass noch keine Schuldaten vorhanden sind.</p><p>In einer MariaDB können mehrere Schemata liegen, die dann einer einzelnen SVWS-Datenbank einer Schule entsprechen, auf die dann mit dem SchILD-Client zugegriffen werden kann.</p><p>In großen Systemen, etwa kommunalen Rechenzentren oder kommerziellen Rechenzentren, könnten noch weitere Schemata in der MariaDB laufen, die dann anderen Schulen gehören oder gar nichts mit Schulen zu tun haben.</p><h3 id="die-unterschiedlichen-nutzer" tabindex="-1">Die unterschiedlichen Nutzer <a class="header-anchor" href="#die-unterschiedlichen-nutzer" aria-label="Permalink to &quot;Die unterschiedlichen Nutzer&quot;">​</a></h3><ul><li>Der <strong>Root-Benutzer</strong> verwaltet den gesamten MariaDB-Server. Er kann Datenbanken und weitere Datenbank-Benutzer anlegen oder löschen. Diese technischen Zugangsdaten gehören zur zuständigen IT. Ein vergessenes root-Kennwort muss administrativ wiederhergestellt werden; Ihr persönliches SchILD-Kennwort ersetzt diesen Zugang nicht.</li><li>Der <strong>Datenbank-Benutzer</strong> verbindet SchILD-NRW 3 mit der Schuldatenbank. Diese einzelne Datenbank heißt auch <strong>Schema</strong>; deshalb wird der Zugang auch Schema-Benutzer genannt. Im beschriebenen Aufbau erhält er Administrationsrechte auf dieses Schema. Welche Datenbanken er tatsächlich verwenden oder löschen darf, legen die MariaDB-Berechtigungen fest. Derselbe Benutzername kann für mehrere Schemata berechtigt sein. In den Beispielen heißt dieser technische Zugang <strong>svwsadmin</strong>.</li><li>Mit einem <strong>SchILD-NRW-3-Benutzer</strong> meldet sich eine Person zur täglichen Arbeit an. Die Benutzerverwaltung legt fest, welche Funktionen diese Person verwenden darf. Mit SchILD-Administrationsrechten stehen zusätzliche Funktionen der Programmoberfläche zur Verfügung. Diese Berechtigungen sind von den Rechten des technischen Datenbank-Zugangs zu unterscheiden.</li></ul>',7),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Über SchILD-NRW lassen sich Benutzergruppen mit Rechten definieren und SchILD-Nutzern zuweisen. Hierüber lassen sich auch sehr hohe Rechte vergeben. Achten Sie bitte darauf, dass Sie auch über Benutzergruppen nur Rechte an Nutzer vergeben, die diese benötigen und haben sollen!")],-1),r('<h3 id="die-ordnerstruktur" tabindex="-1">Die Ordnerstruktur <a class="header-anchor" href="#die-ordnerstruktur" aria-label="Permalink to &quot;Die Ordnerstruktur&quot;">​</a></h3><p>Um die Sicherheit des Betriebssystems zu gewährleisten, stattet Windows die unterschiedlichen Ordner mit unterschiedlichen Rechten aus. Der SVWS-Server und SchILD-NRW 3 fügen sich hier in diesem Sinne korrekt ein. Für die Benutzung des SVWS-Servers und SchILD-NRW werden vier unterschiedliche Verzeichnisse verwendet.</p><ul><li>Das Verzeichnis, in dem der SVWS-Server <em>installiert</em> wird. In diesem Verzeichnis sollen Nutzer nichts ablegen können und <strong>keinen Zugriff - auch nicht nur lesend!</strong> - haben.</li><li>Das Verzeichnis, in dem der SVWS-Server die Datenbanken ablegt. In diesem Verzeichnis hat nur der Server Zugriff, <strong>Nutzer sollen hier nichts lesen</strong> oder verändern können.</li><li>Das Verzeichnis, in dem das reine Programm SchILD-NRW3 installiert wird. <strong>Nutzer haben hier keine Schreibrechte</strong> und es werden hier keine Arbeitsdaten erstellt.</li><li>Das SVWS-Arbeitsverzeichnis, in dem die Daten der Nutzer liegen, zum Beispiel die Reports oder die Export- und Importdateien. Hier haben Nutzer für die tägliche Arbeit Zugriff. Soll dieses Verzeichnis nach der Installation verändert werden, lässt sich dies über die <em>Admin.ini</em> im SchILD-NRW-3-Installationsverzeichnis mit dem Eintrag <code>GroupDir=D:\\SVWS-Arbeitsverzeichnis</code> umstellen.</li></ul><h2 id="systemvoraussetzungen" tabindex="-1">Systemvoraussetzungen <a class="header-anchor" href="#systemvoraussetzungen" aria-label="Permalink to &quot;Systemvoraussetzungen&quot;">​</a></h2><p>SchILD-NRW 3 benötigt einen Windows-Arbeitsplatz und eine dazu passende SVWS-Server-Version. Der SVWS-Server kann je nach gewähltem Installationsverfahren unter Windows oder Linux betrieben werden. Eine Windows-Server-Version wird nicht durch eine Windows-11-Versionsnummer beschrieben.</p><p>Stimmen Sie die konkret unterstützten Betriebssystemversionen und Ressourcen mit der IT und den <a href="https://doku.svws-nrw.de/deployment/" target="_blank" rel="noreferrer">aktuellen Installationsanleitungen des SVWS-Servers</a> ab. Dort sind die Verfahren für Windows, Linux und Container getrennt dokumentiert. Diese Anleitung legt keine eigenen, davon abweichenden Mindestversionen fest.</p><h2 id="datenbankstruktur" tabindex="-1">Datenbankstruktur <a class="header-anchor" href="#datenbankstruktur" aria-label="Permalink to &quot;Datenbankstruktur&quot;">​</a></h2><p>Die Datenbankstruktur für SchILD-NRW 3 wurde grundlegend geändert und zukunftsfähig aufgebaut. Während der Installation des SVWS-Servers können bestehende Access-, MariaDB, MySQL- und MSSQL-Datenbanken in die neue Struktur migriert werden, so dass ein Umstieg von SchILD-NRW 2 zu SchILD-NRW 3 nahtlos möglich ist.</p><h2 id="nicht-unterstutzte-systeme" tabindex="-1">Nicht unterstützte Systeme <a class="header-anchor" href="#nicht-unterstutzte-systeme" aria-label="Permalink to &quot;Nicht unterstützte Systeme&quot;">​</a></h2><p>Die Installation auf einem NAS wird nicht unterstützt.</p><h2 id="installationsubersicht" tabindex="-1">Installationsübersicht <a class="header-anchor" href="#installationsubersicht" aria-label="Permalink to &quot;Installationsübersicht&quot;">​</a></h2><p><a href="/bilder/installation/serverinstallation-schule-svws-und-schild3.png"><img src="'+d+'" alt="Installation innerhalb eines Verwaltungsnetzwerks." loading="lazy"></a></p><p><em>Installation innerhalb eines Verwaltungsnetzwerks.</em></p><p>Der <em>SVWS-Server</em> ist innerhalb des <em>Verwaltungsnetzwerkes</em> der Schule zu installieren.</p><p>Der SVWS-Server selbst läuft er auf einer den - in Bezug auf Hardware und Software - Systemanforderungen entsprechenden MS-Windows- oder Linux-Umgebung.</p><p>Er stellt die <em>MariaDB</em> und eventuelle Dateifreigaben zur Verfügung. SchILD-NRW 3 kann zentral auf dem Server und per Dateifreigabe aufgerufen werden oder einzeln auf Klienten installiert werden.</p><p>Die Kommunikation mit den Klienten läuft über die REST API und ist über HTTPS auf Port 443 zu erreichen. Bei der Installation kann ein Zertifikat erstellt werden, welches in MS Windows hinzuzufügen ist.</p><p>Die Klienten greifen entweder über die Weboberfläche oder ein Klient-Programm wie SchILD-NRW 3 auf den Server zu.</p>',18),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[n("Achten Sie darauf, dass der SVWS-Server weder vom "),e("em",null,"pädagogischen Netzwerk"),n(" der Schule noch direkt von außen über das Internet zu erreichen ist!")])],-1),r('<p>In kleinen Schulen sind auch Einzelplatzinstallationen möglich, bei denen der SVWS-Server mit der MariaDB und der SchILD-NRW-3-Installation auf dem einzelnen Arbeitsplatzrechner laufen.</p><p>Für Dateiaustausche und Zugriffe, sind entsprechende Dateifreigaben einzurichten.</p><ul><li>Auf die Verzeichnisse des <em>SVWS-Servers</em> und das der <em>SVWS-Daten</em> hat niemand außer dem Server selbst Zugriff.</li><li>Die Klienten im <em>Verwaltungsnetz</em>, die ein auf dem Server installiertes SchILD-NRW 3 starten sollen, benötigen Lese-Zugriff auf das <em>Installationsverzeichnis</em> von SchILD-NRW 3.</li><li>Die Arbeitsplatzrechner im <strong>Verwaltungsnetz</strong> benötigen für die Arbeit mit SchILD-NRW 3 Lese- und Schreibrechte im <strong>SVWS-Arbeitsverzeichnis</strong>. Stimmen Sie die Freigaben mit den Rollen an der Schule ab. Nicht alle Personen benötigen Zugriff auf alle Reports. Zusätzlich verwendete Ordner, etwa für Dokumente, Zeugnisse, Im- und Exporte, Notendateien oder Sicherungen, müssen den jeweils berechtigten Personen und Rechnern zur Verfügung stehen.</li></ul><p>Nur die Klienten haben hier als normale Rechner des <em>Verwaltungsnetzwerkes</em> Zugriff auf das Internet.</p><h2 id="nutzer-und-kennworter" tabindex="-1">Nutzer und Kennwörter <a class="header-anchor" href="#nutzer-und-kennworter" aria-label="Permalink to &quot;Nutzer und Kennwörter&quot;">​</a></h2><p><a href="/bilder/installation/kennwoerter-db-schema-schild.jpg"><img src="'+u+'" alt="Das Verhältnis der Nutzer und Kennwörter der MariaDB, des Schemas und der SchILD-NRW-Nutzer." loading="lazy"></a></p><p><em>Das Verhältnis der Nutzer und Kennwörter der MariaDB, des Schemas und der SchILD-NRW-Nutzer.</em></p><p>Das Konzept von SchILD-NRW 3 sieht vor, die Datenbanken von anderen Anwendungen oder Schulen abzuschotten, die ebenfalls auf der MariaDB laufen und auch innerhalb von SchILD-NRW Nutzerrechte vergeben zu können.</p><h3 id="mariadb-root" tabindex="-1">MariaDB-root <a class="header-anchor" href="#mariadb-root" aria-label="Permalink to &quot;MariaDB-root&quot;">​</a></h3><p>Für die Datenbankverwaltung sind der <strong>root-Zugang</strong> und der <strong>Datenbank-Benutzer</strong> zu unterscheiden. Mit dem root-Zugang werden unter anderem Datenbanken angelegt und gelöscht. Ein <strong>Schema</strong> bezeichnet hier eine einzelne Schuldatenbank; es kann bereits Tabellen und Schuldaten enthalten.</p><p>Ein verlorenes root-Kennwort erfordert die Wiederherstellung des technischen Zugangs durch die zuständige IT. Das ist von einem Zurücksetzen persönlicher SchILD-Kennwörter zu unterscheiden.</p><p>Der weitere Nutzer ist der</p><h3 id="schema-admin" tabindex="-1">Schema-Admin <a class="header-anchor" href="#schema-admin" aria-label="Permalink to &quot;Schema-Admin&quot;">​</a></h3><p>Der <strong>Administrator-User von jedem dieser Schemas</strong>, per Standard wird dieser Nutzer <em>svwsadmin</em> genannt, ist aber veränderbar. Für mehrere Schemas können unterschiedliche svws-Admins angelegt werden, es können aber auch mehrere Datenbanken von einem solchen Nutzer verwaltet werden.</p><p>Getrennte Datenbank-Benutzer begrenzen den Zugriff auf die jeweils zugeordneten Schemata. So können auf einem MariaDB-Server beispielsweise mehrere Schuldatenbanken oder Datenbanken anderer Dienste voneinander getrennt betrieben werden.</p><p>Die jeweiligen Zugangsdaten werden im Arbeitsverzeichnis von SchILD-NRW 3 im Ordner &quot;Connection-Files&quot; als <em>[schema].con</em> als Verbindungsinformationen hinterlegt und von SchILD-NRW genutzt, um technisch auf die Datenbank zuzugreifen.</p><p>Hinweise zu den unterschiedlichen Ordnern:</p><ul><li>Das Passwort ist in einer Konfigurationsdatei im <em>SVWS-Server-Datenverzeichnis</em> hinterlegt und daher ist darauf zu achten, dass normale Nutzer keinen Windows-Zugriff auf die Ordner der <em>SVWS-Server-Installation</em> und das <em>SVWS-Server-Datenverzeichnis</em> haben.</li><li>Auf das <em>Installationsverzeichnis von SchILD-NRW 3</em> wird lediglich Lese-Zugriff benötigt, um den Klienten zu starten.</li><li>Alle Nutzer-Zugriffe im Tagesgeschäft auf Dateiebene laufen über das <em>SVWS-Arbeitsverzeichnis</em>, das im Falle einer Neuinstallation (usw.) erhalten bleibt.</li></ul><p>Über diesen Schema-Nutzer kann direkt auf die jeweilige SchILD-Datenbank (das Schema) zugegriffen werden, um im Bedarf ein SchILD-Administrator-Kennwort (SchILD-Nutzer) zurückzusetzen.</p>',19),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Beachten Sie, dass für eigenmächtig veränderte Datenbanken unter Umständen kein Support mehr übernommen werden kann. Kontaktieren Sie bitte in einem solchen Fall unbedingt die Fachberatung der betroffenen Schule.")],-1),e("h3",{id:"schild-nutzer-–-administrator",tabindex:"-1"},[n("SchILD-Nutzer – Administrator "),e("a",{class:"header-anchor",href:"#schild-nutzer-–-administrator","aria-label":'Permalink to "SchILD-Nutzer – Administrator"'},"​")],-1),e("p",null,[e("strong",null,"SchILD-Nutzer mit ihren Rechten"),n(" sind für Schulträger/IT nur bedingt relevant. In der Regel dürfte sich die IT einen Administrator-Nutzer in SchILD-NRW anlegen, so dass im Zweifel Benutzer gesperrt oder neu angelegt und Kennwörter neu gesetzt werden können, ohne manuell in der Datenbank tätig zu werden.")],-1),e("p",null,"Die konkreten Rollen mit ihren jeweiligen Rechten werden innerhalb von SchILD-NRW vergeben und sind schulintern zu organisieren. Der SVWS-Server verwaltet diese Nutzer mit ihren Rechten, daher gelten diese auch für die Zugriffssteuerung über Webinterfaces oder andere Client-Programme.",-1),e("p",null,"Die in den Schulen für die SchILD-Administration verantwortlichen Personen können hierzu die Artikel zum Benutzermanagement von SchILD-NRW konsultieren.",-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Hinweise_f%C3%BCr_IT-Dienstleister",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6911.")],-1)])])}const z=a(o,[["render",h]]);export{D as __pageData,z as default};
